css:
.fx-flr{width:min(680px,100%);display:grid;grid-template-columns:1.2fr 1fr;gap:1.4em}
.fx-flr .plan{display:grid;grid-template-columns:repeat(6,1fr);grid-template-rows:repeat(4,3.6em);gap:3px;padding:3px;border:3px solid var(--text);border-radius:calc(var(--radius)*.5);background:var(--text)}
.fx-flr .plan button{border:0;background:var(--surface);color:var(--text);font:700 .85em var(--font-body);cursor:pointer;transition:background calc(.2s/var(--speed));text-align:center;padding:.3em}
.fx-flr .plan button:hover{background:color-mix(in srgb,var(--accent) 25%,var(--surface))}
.fx-flr .plan button[aria-pressed=true]{background:var(--accent);color:var(--on-accent)}
.fx-flr .a-liv{grid-area:1/1/3/4}.fx-flr .a-kit{grid-area:1/4/3/7}.fx-flr .a-bed{grid-area:3/1/5/3}.fx-flr .a-bath{grid-area:3/3/5/4}.fx-flr .a-bed2{grid-area:3/4/5/7}
.fx-flr .info{border:1px solid var(--border);border-radius:var(--radius);padding:1.1em;background:var(--surface)}
.fx-flr .info h3{font-size:1.25em;margin-bottom:.6em}
.fx-flr .info ul{list-style:none;margin:0;padding:0;display:grid;gap:.4em}
.fx-flr .info li{display:flex;justify-content:space-between;gap:1em;font-size:.92em;border-bottom:1px dashed var(--border);padding-bottom:.4em}
.fx-flr .info li b{color:var(--primary);white-space:nowrap}
@media(max-width:600px){.fx-flr{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){.fx-flr .plan button{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-flr .plan button.is-tap{background:color-mix(in srgb,var(--accent) 25%,var(--surface))}

