(function(){var r=document.querySelector('.fx-flr'),bs=r.querySelectorAll('.plan button'),h=r.querySelector('#fx-flr-h'),l=r.querySelector('#fx-flr-l');
var D={'Living room':[['Feature wall & paint','1,800'],['Flooring (per sq ft)','9'],['Lighting & cove','2,500']],'Kitchen':[['Cabinets (per ft)','480'],['Countertop & backsplash','3,200'],['Wet works','5,500']],'Master bedroom':[['Built-in wardrobe','4,800'],['Bed feature & headboard','2,200'],['Flooring (per sq ft)','9']],'Bathroom':[['Retile & waterproofing','6,500'],['Fixtures & fittings','2,800'],['Vanity cabinet','1,900']],'Second bedroom':[['Study desk & shelf','2,400'],['Wardrobe','3,600'],['Paint','900']]};
function pick(b){bs.forEach(function(x){x.setAttribute('aria-pressed',x===b)});var k=b.dataset.r;h.textContent=k;l.innerHTML=D[k].map(function(x){return '<li><span>'+x[0]+'</span><b>from RM '+x[1]+'</b></li>'}).join('')}
bs.forEach(function(b){b.onclick=function(){pick(b)}});pick(bs[0])})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
